/// Look up GFN1 parameters by atomic number (None when Z > 86).
pub fn get_gfn1_params(z: u8) -> Option<&'static Gfn1ElementParams> {
    if z == 0 || z > 86 {
        return None;
    }
    Some(&GFN1_TABLE[(z - 1) as usize])
}
